<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import { formatDistanceToNow, format, parseISO } from 'date-fns';
import { activityLogsApiService } from 'src/services';
import type { LogExportStatusResponse } from 'src/services/activityLogs/ActivityLogsApiService';
import { useQuasar } from 'quasar';
// JSZip removed - using backend export API instead
import DocBitsTable from '@/components/Table/DocBitsTable.vue';
import LogsAiChat from 'src/components/LogsAiChat.vue';
import { useTranslate } from '@tolgee/vue';
import {
  logMatchesSelectedSeverities,
  normalizeLogSeverity,
} from 'src/utils/logSeverityMatch';

const { t } = useTranslate();

const $q = useQuasar();
const router = useRouter();
const route = useRoute();

// UI state
const logsSection = ref<HTMLElement | null>(null);
// AI chat panel is hidden by default; the reopen tab (v-if="!showAiChat")
// and the panel's own close (X) button toggle it.
const showAiChat = ref(false);
const aiChatWidth = ref(350);

// LogsAiChat is position:fixed at right:0, so the main content area
// must shrink to stop exactly at its left edge. A CSS width:calc(100%
// - Npx) fights unpredictably with Tailwind's own .container max-width
// utility class (see git history for the failed attempts) — measuring
// the real DOM position and computing an explicit pixel width sidesteps
// all of that ambiguity.
//
// Measure from the PARENT's left edge + its own left padding, not
// contentAreaRef's own rect — contentAreaRef's width changes every
// time we set it, and re-measuring its own (now-shrunk) position on
// the next tick creates a feedback loop that converges on a much-too-
// small value. The parent's box never changes size regardless of what
// width we give its child, so it's a stable reference point.
const contentAreaRef = ref<HTMLElement | null>(null);
const aiChatContentWidth = ref(0);
let contentAreaResizeObserver: ResizeObserver | null = null;

function updateAiChatContentWidth() {
  const parent = contentAreaRef.value?.parentElement;
  if (!parent) return;
  const parentRect = parent.getBoundingClientRect();
  const parentPaddingLeft = parseFloat(getComputedStyle(parent).paddingLeft) || 0;
  const contentLeft = parentRect.left + parentPaddingLeft;
  aiChatContentWidth.value = Math.max(
    200,
    window.innerWidth - aiChatWidth.value - contentLeft,
  );
}

// Data state
const loading = ref(false);
const metricsLoading = ref(false);
const logs = ref<any[]>([]);
const displayedLogs = ref<any[]>([]);
// Default to "last_7_days" instead of "today" because low-traffic
// orgs (and any quiet weekday) routinely have zero entries inside the
// today window — leaving users on a blank page that looks broken.
// 7 days covers a normal activity cycle while staying inside the
// indexer's hot retention. Users with a URL state from a previous
// session still see whatever they picked then; this only affects
// fresh-load default.
const selectedTimePreset = ref('last_7_days');
const customStartDate = ref('');
const customEndDate = ref('');
const selectedSeverities = ref<string[]>(['ERROR', 'WARN', 'INFO', 'DEBUG']);
const selectedServices = ref<string[]>([]);
const searchTerm = ref('');
const autoRefresh = ref(false);
const autoRefreshInterval = ref<any>(null);

// Statistics
const logStats = ref({
  total: 0,
  error: 0,
  warn: 0,
  info: 0,
  debug: 0,
  topSource: { name: '-', count: 0 },
  peakTime: { time: '-', count: 0 },
});

// Pagination
const pagination = ref({
  sortBy: 'timestamp',
  descending: true,
  page: 1,
  rowsPerPage: 50,
  rowsNumber: 0,
});

// URL-backed pagination state
const currentPage = ref(1);
const pageSize = ref(50);
const hoursPerPage = ref(1);
const hasNextPage = ref(false);
const hasPreviousPage = ref(false);
const totalPages = ref(0);

// Cursor pagination (unlimited/?hours= mode only). The backend has no
// server-side concept of "page number" for this mode — only "here's the
// next bounded slice" — so we cache each page's cursor client-side as we
// page forward, and pop it to go back. Reset whenever filters/time-range
// change (a fresh query invalidates any cursor from the old one).
const cursorStack = ref<string[]>([]);
const latestNextCursor = ref<string | null>(null);

// updateUrlParams() writes this component's OWN state into the URL via
// router.replace() — that's a real route.query change, so the
// browser-back/forward watcher below fires for it too, indistinguishable
// from the user actually clicking Back. Left unguarded, that watcher's
// initializeFromUrl() call resets currentPage/cursorStack immediately
// after every internal navigation (goToNextPage, filter changes, ...),
// making cursor pagination unusable. This flag lets the watcher tell
// "we just wrote this ourselves" apart from "the user/browser changed it".
let isProgrammaticUrlUpdate = false;

// Time Range Presets
const timePresetOptions = computed(() => {
  // Calculate hours since midnight in user's browser timezone for "Today" filter
  const now = new Date();
  const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
  const hoursSinceMidnight = Math.max(1, Math.ceil((now.getTime() - midnight.getTime()) / (1000 * 60 * 60)));

  return [
    {
      label: t.value('last_hour'),
      value: 'last_hour',
      hours: 1,
    },
    { label: t.value('today'), value: 'today', hours: hoursSinceMidnight },
    {
      label: t.value('last_7_days'),
      value: 'last_7_days',
      hours: 168,
    },
    {
      label: t.value('last_30_days'),
      value: 'last_30_days',
      hours: 720,
    },
    { label: t.value('custom'), value: 'custom', hours: 0 },
  ];
});

// Empty-state escalation: when the current preset returned no logs,
// offer the next wider preset. Order is last_hour → today → last_7_days
// → last_30_days. Stops once we hit last_30_days (30 days is the
// indexer's hot retention) or 'custom' (user picked their own range
// and overriding it would be surprising).
const SUGGESTION_ESCALATION: Record<string, { value: string; labelKey: string }> = {
  last_hour: { value: 'today', labelKey: 'today' },
  today: { value: 'last_7_days', labelKey: 'last_7_days' },
  last_7_days: { value: 'last_30_days', labelKey: 'last_30_days' },
};

const canSuggestLongerRange = computed(
  () => selectedTimePreset.value in SUGGESTION_ESCALATION
);

const suggestionLabelKey = computed(
  () => SUGGESTION_ESCALATION[selectedTimePreset.value]?.labelKey ?? 'last_7_days'
);

function applyLongerRangePreset(): void {
  const next = SUGGESTION_ESCALATION[selectedTimePreset.value];
  if (next) {
    selectedTimePreset.value = next.value;
  }
}

// Backwards-compatible alias — existing source-level tests expect this
// exact function name. New code should call applyLongerRangePreset
// instead.
function applyLastSevenDaysPreset(): void {
  selectedTimePreset.value = 'last_7_days';
}

// Severity Options
const severityOptions = computed(() => [
  { label: 'Debug', value: 'DEBUG', color: 'grey-7', icon: 'bug_report' },
  { label: 'Info', value: 'INFO', color: 'primary', icon: 'info' },
  { label: 'Warning', value: 'WARN', color: 'warning', icon: 'warning' },
  { label: 'Error', value: 'ERROR', color: 'negative', icon: 'error' },
]);

// Service Options - Dynamic Loading
const servicesLoading = ref(false);
const servicesError = ref<string | null>(null);
const availableServices = ref<Array<{ name: string; description: string }>>([]);

/**
 * Initialize component state from URL query parameters
 */
const initializeFromUrl = () => {
  const query = route.query;

  // Parse with validation and defaults.
  // Cursor pagination has no way to reconstruct historical cursors from a
  // URL — they're opaque, server-generated, and only ever obtained by
  // actually walking forward through loadLogs()/goToNextPage(). A
  // deep-link or reload landing on ?page=N>1 with an empty (fresh-mount)
  // cursorStack would otherwise display "Page N" while silently fetching
  // page 1's data. Normalize to page 1 instead — the user can walk
  // forward again from there.
  currentPage.value = 1;
  void query.page; // intentionally ignored — see comment above
  // Any fresh parse of the URL — mount, or a genuine browser back/forward
  // navigating to a different filter/time-range context — invalidates
  // whatever cursors were cached for the OLD context. Only
  // goToNextPage()/goToPreviousPage() are allowed to grow/shrink this
  // stack; every other entry point (including this one) must clear it.
  cursorStack.value = [];
  latestNextCursor.value = null;
  pageSize.value = Math.min(Math.max(1, parseInt(String(query.page_size || '50'), 10)), 1000);
  hoursPerPage.value = Math.min(Math.max(1, parseInt(String(query.hours_per_page || '1'), 10)), 168);

  // Parse log levels. An omitted/invalid param resets to the default (all
  // 4 selected) rather than leaving whatever was set before this parse —
  // this function runs on every genuine browser-nav, not just mount, so a
  // stale value here would silently outlive the URL that no longer names it.
  // Only reassign when the computed value actually differs — selectedSeverities/
  // selectedServices each have their own watch() that refetches on change,
  // and a fresh array literal is a new reference even with identical
  // content, which would fire that watcher (and refetch) needlessly on
  // every single initializeFromUrl() call, mount included.
  const levels = query.log_level
    ? String(query.log_level).split(',').map(l => l.trim().toUpperCase())
    : [];
  const validLevels = levels.filter(l => ['ERROR', 'WARN', 'INFO', 'DEBUG'].includes(l));
  const newSeverities = validLevels.length > 0
    ? validLevels
    : ['ERROR', 'WARN', 'INFO', 'DEBUG'];
  if (JSON.stringify(newSeverities) !== JSON.stringify(selectedSeverities.value)) {
    selectedSeverities.value = newSeverities;
  }

  // Parse services
  const newServices = query.services
    ? String(query.services).split(',').map(s => s.trim())
    : [];
  if (JSON.stringify(newServices) !== JSON.stringify(selectedServices.value)) {
    selectedServices.value = newServices;
  }

  // Parse search term
  searchTerm.value = query.search ? String(query.search) : '';

  // Parse time preset
  const validPresets = ['last_hour', 'today', 'last_7_days', 'last_30_days', 'custom'];
  const preset = query.time_preset ? String(query.time_preset) : '';
  selectedTimePreset.value = validPresets.includes(preset) ? preset : 'last_7_days';

  // Parse custom date range
  customStartDate.value = query.start_date ? String(query.start_date) : '';
  customEndDate.value = query.end_date ? String(query.end_date) : '';

  console.log('[ACTIVITY LOGS] Initialized from URL:', {
    page: currentPage.value,
    pageSize: pageSize.value,
    hoursPerPage: hoursPerPage.value,
    severities: selectedSeverities.value,
    services: selectedServices.value,
    search: searchTerm.value,
    timePreset: selectedTimePreset.value,
    customStartDate: customStartDate.value,
    customEndDate: customEndDate.value,
  });
};

/**
 * Update URL query parameters without adding to browser history
 */
const updateUrlParams = () => {
  const query: Record<string, string> = {
    page: String(currentPage.value),
    page_size: String(pageSize.value),
    hours_per_page: String(hoursPerPage.value),
  };

  // Include time preset whenever it differs from the component default
  // ('last_7_days'). Persisting the chosen preset means reloads /
  // back-navigation restore exactly what the user picked instead of
  // silently snapping back to the default.
  if (selectedTimePreset.value && selectedTimePreset.value !== 'last_7_days') {
    query.time_preset = selectedTimePreset.value;
  }

  // Include custom date range if preset is 'custom'
  if (selectedTimePreset.value === 'custom') {
    if (customStartDate.value) {
      query.start_date = customStartDate.value;
    }
    if (customEndDate.value) {
      query.end_date = customEndDate.value;
    }
  }

  // Include non-default filters
  if (selectedSeverities.value.length > 0 && selectedSeverities.value.length < 4) {
    query.log_level = selectedSeverities.value.join(',');
  }

  if (selectedServices.value.length > 0) {
    query.services = selectedServices.value.join(',');
  }

  if (searchTerm.value?.trim()) {
    query.search = searchTerm.value.trim();
  }

  // Use replace() to avoid cluttering browser history
  isProgrammaticUrlUpdate = true;
  router
    .replace({ path: route.path, query })
    .catch(err => {
      // Ignore NavigationDuplicated errors
      if (err.name !== 'NavigationDuplicated') {
        console.error('[ACTIVITY LOGS] URL update error:', err);
      }
    })
    .finally(() => {
      // Clear one full tick after the navigation settles, so the
      // browser-nav watcher below (which fires as a *reaction* to this
      // same route.query change) definitely sees the flag still set.
      nextTick(() => {
        isProgrammaticUrlUpdate = false;
      });
    });

  console.log('[ACTIVITY LOGS] Updated URL:', query);
};

