/**
 * Handle column sort change from ColumnOrderBy component
 * Updates pagination state and re-filters logs to apply sorting
 */
const handleColumnSort = (event: { column: string; direction: 'asc' | 'desc' }) => {
  pagination.value.sortBy = event.column;
  pagination.value.descending = event.direction === 'desc';
  filterLogs(); // Re-sort the displayed logs
};

const toggleSeverity = (severity: string) => {
  // Use immutable operations to avoid need for deep watcher.
  // Mutating selectedSeverities here is enough — the watch(selectedSeverities,
  // ...) below already calls resetToFirstPage()+loadLogs() on any change,
  // so calling them again here would double-fetch on every toggle.
  if (selectedSeverities.value.includes(severity)) {
    // Immutable removal using filter
    selectedSeverities.value = selectedSeverities.value.filter((s) => s !== severity);
  } else {
    // Immutable addition using spread
    selectedSeverities.value = [...selectedSeverities.value, severity];
  }
};

// Guards against stale in-flight responses overwriting fresher state — if
// a filter/page change fires a new loadLogs() while an older one is still
// in flight, the older one's response can resolve AFTER the newer one's
// and clobber latestNextCursor/pagination with outdated data. Only the
// most recently STARTED call is allowed to apply its result.
let loadLogsRequestId = 0;

// Return value distinguishes three outcomes, not two: `true`/`false` mean
// this call was the LATEST one and genuinely succeeded/failed; `null`
// means it was superseded by a newer loadLogs() call before it resolved
// (e.g. a filter change fired while a goToNextPage() request was still in
// flight). Callers like goToNextPage()/goToPreviousPage() roll back their
// own state on `false` (a real failure of THEIR OWN request) but must
// treat `null` as "some newer call already owns the state, do nothing" —
// otherwise a superseded page-navigation's rollback would stomp whatever
// the newer (e.g. filter-reset) call already put in place.
const loadLogs = async (): Promise<boolean | null> => {
  const requestId = ++loadLogsRequestId;
  try {
    loading.value = true;

    // Determine hours based on preset or custom range
    let hours = 1;
    const preset = timePresetOptions.value.find(
      (p) => p.value === selectedTimePreset.value,
    );
    if (preset && preset.value !== 'custom') {
      hours = preset.hours;
    } else if (
      selectedTimePreset.value === 'custom' &&
      customStartDate.value &&
      customEndDate.value
    ) {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Build API parameters with time-window pagination
    const params: any = {
      page: currentPage.value, // Dynamic from URL/state
      page_size: pageSize.value, // Dynamic from URL/state
      hours, // Pass the full hours value based on selected time preset
    };

    // Add severity filter
    if (
      selectedSeverities.value.length > 0 &&
      selectedSeverities.value.length < 4
    ) {
      params.log_level = selectedSeverities.value.join(',');
    }

    // Add service filter
    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    // Cursor pagination: only meaningful once we've paged forward at least
    // once (cursorStack holds each visited page's continuation token).
    if (cursorStack.value.length > 0) {
      params.cursor = cursorStack.value[cursorStack.value.length - 1];
    }

    // Fetch logs and metrics in parallel
    const [logsResponse] = await Promise.all([
      activityLogsApiService.getOrganizationLogs(params),
      loadMetrics(requestId), // Load metrics separately for better performance
    ]);

    if (requestId !== loadLogsRequestId) {
      // A newer loadLogs() call started while this one was in flight —
      // that one (or a later one) owns the source of truth now. null (not
      // false) so callers don't mistake this for a genuine failure of
      // their own request and roll back state the newer call already set.
      return null;
    }

    logs.value = logsResponse.logs || [];

    // Apply client-side filtering
    filterLogs();

    // Update pagination metadata from API response
    // The API returns pagination info which may not be typed yet
    const apiResponse = logsResponse as any;
    if (apiResponse.pagination) {
      // If backend returns full pagination metadata
      pagination.value.rowsNumber = apiResponse.pagination.total_entries || 0;
      // Cursor pagination: the backend has no page-number concept for this
      // mode, only "is there a next slice" (next_cursor) — has_previous_page
      // is purely a client-side fact (do we have a cached cursor to pop).
      latestNextCursor.value = apiResponse.pagination.next_cursor ?? null;
      hasNextPage.value = latestNextCursor.value !== null;
      hasPreviousPage.value = cursorStack.value.length > 0;
      totalPages.value = apiResponse.pagination.total_pages || 0;
    } else {
      // Fallback: the backend returned no pagination metadata at all (an
      // unexpected/malformed response shape). We can't tell whether more
      // pages exist without it — page-number arithmetic doesn't apply to
      // cursor mode, so guessing via currentPage/totalPages here would
      // silently enable Next with no cursor to actually send. Be
      // conservative: assume this is the only page.
      pagination.value.rowsNumber = logsResponse.total_entries || 0;
      totalPages.value = 1;
      latestNextCursor.value = null;
      hasNextPage.value = false;
      hasPreviousPage.value = cursorStack.value.length > 0;
    }

    console.log('[ACTIVITY LOGS] Loaded logs:', {
      total: logs.value.length,
      params,
      response: logsResponse,
    });
    return true;
  } catch (error) {
    if (requestId !== loadLogsRequestId) {
      // Stale error from a superseded request — the newer call already
      // owns the loading/error state, don't stomp it. null, not false —
      // same reasoning as the success-path stale check above.
      return null;
    }
    console.error('[ACTIVITY LOGS] Error loading logs:', error);
    notify.error(t.value('error_loading'), error instanceof Error ? error.message : 'Unknown error');
    return false;
  } finally {
    if (requestId === loadLogsRequestId) {
      loading.value = false;
    }
  }
};

/**
 * Navigate to next page
 */
const goToNextPage = async () => {
  if (hasNextPage.value && !loading.value) {
    const cursorPushed = latestNextCursor.value;
    const previousPage = currentPage.value;
    if (cursorPushed) {
      cursorStack.value.push(cursorPushed);
    }
    currentPage.value++;
    updateUrlParams();
    const result = await loadLogs();
    // Only a genuine failure (false) of THIS OWN request warrants a
    // rollback. null means a newer call (e.g. a filter change) superseded
    // this one before it resolved — that newer call already owns
    // cursorStack/currentPage, and rolling back here would stomp it.
    if (result === false) {
      // Roll back — a failed request must not leave the cursor stack or
      // displayed page pointing somewhere nothing was ever loaded for.
      if (cursorPushed) {
        cursorStack.value.pop();
      }
      currentPage.value = previousPage;
      updateUrlParams();
    }
  }
};

/**
 * Navigate to previous page
 */
const goToPreviousPage = async () => {
  if (hasPreviousPage.value && currentPage.value > 1 && !loading.value) {
    const poppedCursor = cursorStack.value.pop();
    const previousPage = currentPage.value;
    currentPage.value--;
    updateUrlParams();
    const result = await loadLogs();
    // See goToNextPage()'s comment — only a genuine `false` failure of
    // this own request rolls back; `null` (superseded) must not.
    if (result === false) {
      if (poppedCursor !== undefined) {
        cursorStack.value.push(poppedCursor);
      }
      currentPage.value = previousPage;
      updateUrlParams();
    }
  }
};

/**
 * Reset to first page (called when filters change)
 */
const resetToFirstPage = () => {
  cursorStack.value = [];
  latestNextCursor.value = null;
  if (currentPage.value !== 1) {
    currentPage.value = 1;
    updateUrlParams();
  }
};

/**
 * Load organization logs metrics (severity counts)
 * Called separately from loadOrganizationLogs for faster metrics display
 */
const loadMetrics = async (requestId: number) => {
  // Tied to the SAME generation counter loadLogs() uses (it's always the
  // caller, in the same Promise.all) rather than its own — metrics and
  // logs represent the same logical "page load" and must go stale
  // together. No longer gated by metricsLoading as an early-return mutex:
  // that guard used to silently DROP a legitimately newer fetch whenever
  // an older one hadn't finished yet, which is worse than the staleness
  // problem it was meant to prevent — a superseded call could then be the
  // ONLY one that ever ran, permanently leaving stale counts on screen.
  metricsLoading.value = true;

  try {
    // Calculate time range for metrics query
    let hours = 1;
    if (selectedTimePreset.value === 'last_hour') {
      hours = 1;
    } else if (selectedTimePreset.value === 'today') {
      hours = 24;
    } else if (selectedTimePreset.value === 'last_7_days') {
      hours = 168;
    } else if (selectedTimePreset.value === 'last_30_days') {
      hours = 720; // 30 days = 720 hours (will be capped at 24 by backend)
    } else if (selectedTimePreset.value === 'custom') {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Build metrics API parameters
    const params: any = {
      hours_per_page: hours, // Send actual hours from time range selection
    };

    // Add severity filter
    if (
      selectedSeverities.value.length > 0 &&
      selectedSeverities.value.length < 4
    ) {
      params.log_level = selectedSeverities.value.join(',');
    }

    // Add service filter
    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    // Fetch metrics
    const response = await activityLogsApiService.getOrganizationMetrics(params);

    if (requestId !== loadLogsRequestId) {
      // Superseded by a newer loadLogs() call — its own loadMetrics()
      // owns logStats now, applying this stale response would overwrite
      // correct counts for the new filter with counts for the old one.
      return;
    }

    // API returns counts in nested severity_counts object
    const errorCount = response.severity_counts?.error_count ?? 0;
    const warningCount = response.severity_counts?.warning_count ?? 0;
    const infoCount = response.severity_counts?.info_count ?? 0;
    const debugCount = response.severity_counts?.debug_count ?? 0;
    const totalCount = response.severity_counts?.total ?? 0;

    // Extract peak activity and top source from response
    const peakActivity = response.peak_activity || { time: '-', count: 0 };
    const topSource = response.top_source || { name: '-', count: 0 };

    // Update stats with API response
    logStats.value = {
      total: totalCount || 0,
      error: errorCount || 0,
      warn: warningCount || 0,
      info: infoCount || 0,
      debug: debugCount || 0,
      topSource: topSource,
      peakTime: peakActivity,
    };

    console.log('[ACTIVITY LOGS] Loaded metrics:', {
      params,
      response,
      stats: logStats.value,
    });
  } catch (error) {
    if (requestId !== loadLogsRequestId) {
      return; // stale error from a superseded call — ignore
    }
    console.error('[ACTIVITY LOGS] Error loading metrics:', error);
    // Don't show error notification for metrics - logs still work
    // Metrics will show 0 if this fails
  } finally {
    if (requestId === loadLogsRequestId) {
      metricsLoading.value = false;
    }
  }
};

const filterLogs = () => {
  let filtered = [...logs.value];

  // Filter by severity (defense-in-depth - backend should also filter).
  // Backend rows store the raw log source's level, which for WARN is
  // frequently "WARNING" (Python's logging module spelling) rather than
  // the UI's canonical "WARN" — the backend's own search-side filter
  // already treats these as aliases (see _build_level_filter), so this
  // client-side re-check must too, or it silently drops every row whose
  // raw level says "WARNING" even though the user selected "Warning".
  if (selectedSeverities.value.length < 4) {
    filtered = filtered.filter((log) =>
      logMatchesSelectedSeverities(log.level, selectedSeverities.value),
    );
  }

  // Filter by service (defense-in-depth - backend should also filter).
  // The org-logs endpoint returns the producing service under `service`
  // — `module` is a legacy alias that is almost always null. Read both
  // so we keep working if a row somewhere still uses the old shape.
  if (selectedServices.value.length > 0) {
    filtered = filtered.filter((log) =>
      selectedServices.value.includes(log.service || log.module),
    );
  }

  // Filter by search term
  if (searchTerm.value) {
    const search = searchTerm.value.toLowerCase();
    filtered = filtered.filter((log) => {
      // 1. Check basic fields (Message, Service, Organization). Read
      // both `service` (current API field) and `module` (legacy) so
      // user search of e.g. "ftp-import" hits the right rows.
      if (
        log.message?.toLowerCase().includes(search) ||
        log.service?.toLowerCase().includes(search) ||
        log.module?.toLowerCase().includes(search) ||
        log.organization_name?.toLowerCase().includes(search)
      ) {
        return true;
      }

      // 2. Check Metadata
      if (log.metadata) {
        const metadataStr = JSON.stringify(log.metadata).toLowerCase();
        if (metadataStr.includes(search)) return true;
      }

      // 3. Check Structured Log content (often contains the real error details)
      if (log.log) {
        const logContent =
          typeof log.log === 'string'
            ? log.log.toLowerCase()
            : JSON.stringify(log.log).toLowerCase();
        if (logContent.includes(search)) return true;
      }

      return false;
    });
  }

  // Apply sorting based on pagination state
  if (pagination.value.sortBy) {
    filtered.sort((a, b) => {
      let aVal = a[pagination.value.sortBy];
      let bVal = b[pagination.value.sortBy];

      // Handle null/undefined values
      if (aVal == null && bVal == null) return 0;
      if (aVal == null) return pagination.value.descending ? -1 : 1;
      if (bVal == null) return pagination.value.descending ? 1 : -1;

      // Handle numeric comparison
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return pagination.value.descending ? bVal - aVal : aVal - bVal;
      }

      // Handle string comparison
      if (typeof aVal === 'string' && typeof bVal === 'string') {
        const comparison = aVal.localeCompare(bVal);
        return pagination.value.descending ? -comparison : comparison;
      }

      // Handle date comparison
      if (pagination.value.sortBy === 'timestamp') {
        const aTime = new Date(aVal).getTime();
        const bTime = new Date(bVal).getTime();
        return pagination.value.descending ? bTime - aTime : aTime - bTime;
      }

      // Default fallback
      return 0;
    });
  }

  displayedLogs.value = filtered;
  pagination.value.rowsNumber = filtered.length;

  // Fallback: If API metrics returned 0 total but we have logs, calculate from client data
  // This ensures charts and badges work even if the metrics endpoint is lagging or empty
  if (logStats.value.total === 0 && logs.value.length > 0) {
    calculateStats(logs.value);
  }
};

const calculateStats = (logsToCount = logs.value) => {
  logStats.value = {
    total: logsToCount.length,
    error: logsToCount.filter((log) => normalizeLogSeverity(log.level) === 'ERROR').length,
    warn: logsToCount.filter((log) => normalizeLogSeverity(log.level) === 'WARN').length,
    info: logsToCount.filter((log) => normalizeLogSeverity(log.level) === 'INFO').length,
    debug: logsToCount.filter((log) => normalizeLogSeverity(log.level) === 'DEBUG').length,
    topSource: logStats.value.topSource || { name: '-', count: 0 },
    peakTime: logStats.value.peakTime || { time: '-', count: 0 },
  };
};

/**
 * Parse timestamp in both formats: ISO 8601 strings or epoch milliseconds
 * Handles backend format change from ISO strings to epoch milliseconds
 */
const parseTimestamp = (timestamp: string | number): Date => {
  if (typeof timestamp === 'number') {
    return new Date(timestamp);
  }
  // Try to parse as number (epoch ms) if string is numeric
  const asNumber = Number(timestamp);
  if (!isNaN(asNumber) && asNumber > 0) {
    return new Date(asNumber);
  }
  // Fall back to ISO parsing
  return parseISO(timestamp);
};

const formatRelativeTime = (timestamp: string | number): string => {
  try {
    return formatDistanceToNow(parseTimestamp(timestamp), { addSuffix: true });
  } catch (error) {
    return String(timestamp);
  }
};

const formatAbsoluteTime = (timestamp: string | number): string => {
  try {
    return format(parseTimestamp(timestamp), 'MMM dd, yyyy HH:mm:ss');
  } catch (error) {
    return String(timestamp);
  }
};

const getSeverityColor = (severity: string): string => {
  const colors: Record<string, string> = {
    ERROR: 'negative',
    WARN: 'warning',
    INFO: 'primary',
    DEBUG: 'grey-7',
  };
  return colors[normalizeLogSeverity(severity)] || 'grey';
};

