const truncateMessage = (message: string, maxLength = 200): string => {
  if (message.length <= maxLength) return message;
  return message.substring(0, maxLength) + '...';
};

/**
 * Check if a string is valid JSON
 */
const isJsonString = (str: string): boolean => {
  try {
    const parsed = JSON.parse(str);
    return typeof parsed === 'object' && parsed !== null;
  } catch {
    return false;
  }
};

/**
 * Format JSON string with proper indentation
 */
const formatJson = (str: string): string => {
  try {
    const parsed = JSON.parse(str);
    return JSON.stringify(parsed, null, 2);
  } catch {
    return str;
  }
};

/**
 * Get formatted message for display
 * Detects JSON and formats it nicely
 */
const getFormattedMessage = (message: string): string => {
  if (isJsonString(message)) {
    return formatJson(message);
  }
  return message;
};

/**
 * Copy text to clipboard
 */
const copyToClipboard = async (text: string) => {
  try {
    await navigator.clipboard.writeText(text);
    notify.success('Copied to clipboard', { duration: 1500 });
  } catch (error) {
    console.error('Failed to copy:', error);
    notify.error('Failed to copy to clipboard');
  }
};

/**
 * Extract and parse the 'log' field from a log entry
 * Many log entries have a 'log' field containing the actual structured log message
 */
const getStructuredLog = (row: any): any | null => {
  if (!row.log) return null;

  try {
    // The 'log' field is typically a JSON string
    if (typeof row.log === 'string') {
      return JSON.parse(row.log);
    }
    // Or it might already be parsed
    if (typeof row.log === 'object') {
      return row.log;
    }
  } catch (error) {
    console.warn('[ACTIVITY LOGS] Failed to parse log field:', error);
  }

  return null;
};

/**
 * Get the best message to display for a log entry
 * Prioritizes the 'log' field's message over the top-level message
 */
const getDisplayMessage = (row: any): string => {
  const structuredLog = getStructuredLog(row);

  // If we have a structured log with a message, use that
  if (structuredLog && structuredLog.message) {
    return structuredLog.message;
  }

  // Fall back to top-level message
  return row.message || 'No message';
};

/**
 * Get the formatted structured log for display
 * Returns the full structured log as formatted JSON
 */
const getFormattedStructuredLog = (row: any): string => {
  const structuredLog = getStructuredLog(row);

  if (structuredLog) {
    return JSON.stringify(structuredLog, null, 2);
  }

  // Fall back to the raw log field if it exists
  if (row.log) {
    if (typeof row.log === 'string') {
      return formatJson(row.log);
    }
    return JSON.stringify(row.log, null, 2);
  }

  // Last resort: format the message field
  return getFormattedMessage(row.message);
};

/**
 * Attempt to parse known log formats into structured data
 */
const parseLogMessage = (message: string): any | null => {
  // Check for "LEVEL - TIME - LOGGER - STATUS - MESSAGE" pattern
  // Example: INFO - 08:01:02 - helpers.enhanced_auth_logger - ✅ AUTH_SUCCESS - Auth...
  const parts = message.split(' - ');
  if (parts.length >= 4) {
    const [level, time, logger, status, ...rest] = parts;
    // Basic validation to ensure it's likely our format
    if (['INFO', 'ERROR', 'WARN', 'DEBUG'].includes(level) && time.includes(':')) {
      return {
        level,
        time,
        logger,
        status,
        message: rest.join(' - ')
      };
    }
  }
  return null;
};

/**
 * Check if a log entry has a structured log field
 */
const hasStructuredLog = (row: any): boolean => {
  return getStructuredLog(row) !== null;
};

/**
 * Copy the full log entry as JSON (all fields)
 */
const copyFullLogEntry = async (row: any) => {
  try {
    const fullLog = JSON.stringify(row, null, 2);
    await navigator.clipboard.writeText(fullLog);
    notify.success('Full log entry copied to clipboard', { duration: 1500 });
  } catch (error) {
    console.error('Failed to copy full log entry:', error);
    notify.error('Failed to copy log entry');
  }
};

const onRowClick = (event: Event, row: any, index: number) => {
  router.push({
    path: `/settings/event-logs/detail/${row.id}`,
    state: {
      log: JSON.parse(JSON.stringify(row)), // Current log
      logsArray: JSON.parse(JSON.stringify(displayedLogs.value)), // Full list of displayed logs
      logIndex: index, // Index of current log
    }
  });
};

const toggleAutoRefresh = (enabled: boolean) => {
  if (enabled) {
    autoRefreshInterval.value = setInterval(() => {
      loadLogs();
    }, 30000); // 30 seconds
    notify.success('Auto-refresh enabled', { description: 'Logs will refresh every 30 seconds' });
  } else {
    if (autoRefreshInterval.value) {
      clearInterval(autoRefreshInterval.value);
      autoRefreshInterval.value = null;
    }
    notify.info('Auto-refresh disabled');
  }
};

const exportLogs = () => {
  try {
    const dataStr = JSON.stringify(displayedLogs.value, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `activity-logs-${format(new Date(), 'yyyy-MM-dd-HHmmss')}.json`;
    link.click();
    URL.revokeObjectURL(url);

    notify.success('Logs exported successfully');
  } catch (error) {
    console.error('[ACTIVITY LOGS] Export error:', error);
    notify.error('Failed to export logs');
  }
};

/**
 * Backend Log Export State
 * Uses async export API with S3 storage for large exports
 */
const isDownloading = ref(false);
const exportList = ref<LogExportStatusResponse[]>([]);
const exportPollingInterval = ref<ReturnType<typeof setInterval> | null>(null);

/**
 * Request a backend log export
 * Uses async API with S3 storage - handles large exports beyond 5000 limit
 */
const downloadLogsAsZip = async () => {
  isDownloading.value = true;

  try {
    // Calculate time range based on preset
    let timeRangeStart: Date;
    let timeRangeEnd: Date = new Date();

    const preset = timePresetOptions.value.find(p => p.value === selectedTimePreset.value);
    if (selectedTimePreset.value === 'custom' && customStartDate.value && customEndDate.value) {
      timeRangeStart = new Date(customStartDate.value);
      timeRangeEnd = new Date(customEndDate.value);
    } else if (preset) {
      timeRangeStart = new Date(Date.now() - preset.hours * 60 * 60 * 1000);
    } else {
      timeRangeStart = new Date(Date.now() - 24 * 60 * 60 * 1000); // Default 24h
    }

    // Build export request params
    const params: any = {
      time_range_start: timeRangeStart.toISOString(),
      time_range_end: timeRangeEnd.toISOString(),
    };

    if (selectedSeverities.value.length > 0 && selectedSeverities.value.length < 4) {
      params.log_levels = selectedSeverities.value.join(',');
    }

    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    if (searchTerm.value?.trim()) {
      params.search_query = searchTerm.value.trim();
    }

    console.log('[ACTIVITY LOGS] Requesting export:', params);

    // Request export from backend
    const exportResponse = await activityLogsApiService.requestLogExport(params);

    console.log('[ACTIVITY LOGS] Export requested:', exportResponse);

    notify.success('Export requested', { description: 'Processing in background. Download link will appear when ready.' });

    // Refresh export list and start polling
    await loadExportList();
    startExportPolling();

  } catch (error: any) {
    console.error('[ACTIVITY LOGS] Export request error:', error);

    // Handle rate limit error
    if (error?.response?.status === 429) {
      notify.warning('Export limit reached', { description: 'Maximum 3 pending exports allowed. Wait for current exports to complete.' });
    } else {
      notify.error('Failed to request export', error?.response?.data?.detail || error?.message || 'Unknown error');
    }
  } finally {
    isDownloading.value = false;
  }
};

/**
 * Load list of recent exports for the organization
 */
const loadExportList = async () => {
  try {
    const response = await activityLogsApiService.getLogExportList();
    exportList.value = response.exports || [];
    console.log('[ACTIVITY LOGS] Export list loaded:', exportList.value.length, 'exports');
  } catch (error) {
    console.error('[ACTIVITY LOGS] Failed to load export list:', error);
  }
};

/**
 * Start polling for export status updates
 */
const startExportPolling = () => {
  // Don't start if already polling
  if (exportPollingInterval.value) return;

  // Check if there are any pending/processing exports
  const hasPendingExports = exportList.value.some(
    e => e.status === 'pending' || e.status === 'processing'
  );

  if (!hasPendingExports) return;

  console.log('[ACTIVITY LOGS] Starting export status polling');

  exportPollingInterval.value = setInterval(async () => {
    await loadExportList();

    // Check if any export completed
    const hasPending = exportList.value.some(
      e => e.status === 'pending' || e.status === 'processing'
    );

    // Show notification for newly ready exports
    const readyExports = exportList.value.filter(e => e.status === 'ready' && e.download_available);
    if (readyExports.length > 0) {
      const latestReady = readyExports[0];
      const logCountText = latestReady.log_count ? `${latestReady.log_count.toLocaleString()} logs` : '';
      const fileSizeText = latestReady.file_size_bytes
        ? `${(latestReady.file_size_bytes / 1024 / 1024).toFixed(2)} MB`
        : '';

      notify.success('Export ready for download', { description: [logCountText, fileSizeText].filter(Boolean).join(' • ') });
    }

    // Stop polling if no more pending exports
    if (!hasPending) {
      stopExportPolling();
    }
  }, 10000); // Poll every 10 seconds
};

/**
 * Stop export status polling
 */
const stopExportPolling = () => {
  if (exportPollingInterval.value) {
    console.log('[ACTIVITY LOGS] Stopping export status polling');
    clearInterval(exportPollingInterval.value);
    exportPollingInterval.value = null;
  }
};

/**
 * Download a completed export
 */
const downloadExport = (exportItem: LogExportStatusResponse) => {
  if (!exportItem.download_available) {
    notify.warning('Export not ready', { description: `Current status: ${exportItem.status}` });
    return;
  }

  const downloadUrl = activityLogsApiService.getLogExportDownloadUrl(exportItem.id);

  // Open download in new tab (will trigger file download)
  window.open(downloadUrl, '_blank');

  notify.info('Starting download...');
};

/**
 * Delete/cancel an export
 */
const deleteExport = async (exportItem: LogExportStatusResponse) => {
  try {
    await activityLogsApiService.deleteLogExport(exportItem.id);
    await loadExportList();

    notify.success('Export deleted');
  } catch (error) {
    console.error('[ACTIVITY LOGS] Failed to delete export:', error);
    notify.error('Failed to delete export');
  }
};

/**
 * Format file size in human readable format
 */
const formatFileSize = (bytes: number | undefined): string => {
  if (!bytes) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`;
};

/**
 * Get status color for export badge
 */
const getExportStatusColor = (status: string): string => {
  const colors: Record<string, string> = {
    pending: 'orange',
    processing: 'blue',
    ready: 'positive',
    failed: 'negative',
    expired: 'grey',
  };
  return colors[status] || 'grey';
};

/**
 * Check if there are any pending/processing exports
 */
const hasPendingExports = computed(() =>
  exportList.value.some(e => e.status === 'pending' || e.status === 'processing')
);

/**
 * Calculate appropriate interval for time series chart based on time range
 *
 * @param hours - Total hours in time range
 * @returns Object with intervalMs and intervalLabel
 */
const calculateChartInterval = (hours: number): { intervalMs: number; intervalLabel: string } => {
  if (hours <= 1) {
    // 1 hour or less: 5-minute intervals
    return { intervalMs: 5 * 60 * 1000, intervalLabel: '5-minute' };
  } else if (hours <= 6) {
    // 6 hours or less: 15-minute intervals
    return { intervalMs: 15 * 60 * 1000, intervalLabel: '15-minute' };
  } else if (hours <= 24) {
    // 24 hours or less: 1-hour intervals
    return { intervalMs: 60 * 60 * 1000, intervalLabel: 'hourly' };
  } else if (hours <= 72) {
    // 3 days or less: 3-hour intervals
    return { intervalMs: 3 * 60 * 60 * 1000, intervalLabel: '3-hour' };
  } else {
    // More than 3 days: 6-hour intervals
    return { intervalMs: 6 * 60 * 60 * 1000, intervalLabel: '6-hour' };
  }
};

// Reload data when time preset changes
watch(selectedTimePreset, () => {
  console.log('[ACTIVITY LOGS] Time preset changed to:', selectedTimePreset.value);
  resetToFirstPage();
  updateUrlParams();
  loadLogs();
});

// No deep: true needed - using immutable operations in toggleSeverity
watch(selectedSeverities, () => {
  console.log('[ACTIVITY LOGS] Severity filters changed:', selectedSeverities.value);
  resetToFirstPage();
  updateUrlParams();
  loadLogs();
});

// No deep: true needed - selectedServices is replaced, not mutated
watch(selectedServices, () => {
  console.log('[ACTIVITY LOGS] Service filters changed:', selectedServices.value);
  resetToFirstPage();
  updateUrlParams();
  loadLogs();
});

// Reload data when custom date range changes
watch([customStartDate, customEndDate], () => {
  if (customStartDate.value && customEndDate.value) {
    console.log('[ACTIVITY LOGS] Custom date range changed:', {
      start: customStartDate.value,
      end: customEndDate.value,
    });
    resetToFirstPage();
    updateUrlParams();
    loadLogs();
  }
});

// Search term watcher with debouncing
let searchTimeout: any;
watch(searchTerm, () => {
  clearTimeout(searchTimeout);
  searchTimeout = setTimeout(() => {
    console.log('[ACTIVITY LOGS] Search term changed:', searchTerm.value);
    resetToFirstPage();
    updateUrlParams();
    loadLogs();
  }, 500);
});

/**
 * Handle browser back/forward button navigation
 */
watch(
  () => route.query,
  (newQuery, oldQuery) => {
    // Prevent infinite loop - skip if query hasn't actually changed
    if (JSON.stringify(newQuery) === JSON.stringify(oldQuery)) {
      return;
    }

    // Skip our own updateUrlParams() writes — see isProgrammaticUrlUpdate's
    // declaration. Only real browser back/forward or a pasted/edited URL
    // should re-initialize state; the component's own internal navigation
    // (goToNextPage, filter changes, ...) already updated everything it
    // needs to directly and must not have it stomped right back.
    if (isProgrammaticUrlUpdate) {
      return;
    }

    console.log('[ACTIVITY LOGS] Browser navigation detected, reinitializing from URL');
    initializeFromUrl();
    loadLogs();
  },
  { deep: true }
);

// Lifecycle
onMounted(async () => {
  // Measure and wire up resize listening synchronously, before any
  // awaited network call below — this guarantees onBeforeUnmount always
  // has a listener to remove even if the component unmounts mid-fetch,
  // and avoids a 0px-wide content flash while those awaits are pending.
  // This first measurement can still be wrong though: SettingsLayout keeps
  // its body v-show-hidden until an async userStore.getProfile() resolves,
  // so contentAreaRef's parent can still be at its hidden/zero-ish size
  // when this runs — a stale-too-early read a fixed setTimeout/rAF delay
  // can't reliably outlast. A ResizeObserver on the parent re-measures
  // exactly when that layout actually settles, whenever that happens.
  updateAiChatContentWidth();
  window.addEventListener('resize', updateAiChatContentWidth);
  if (contentAreaRef.value?.parentElement) {
    contentAreaResizeObserver = new ResizeObserver(() => updateAiChatContentWidth());
    contentAreaResizeObserver.observe(contentAreaRef.value.parentElement);
  }

  initializeFromUrl(); // Initialize state from URL query parameters first
  await loadAvailableServices(); // Load services
  await Promise.all([
    loadLogs(), // Load logs with state from URL
    loadExportList(), // Load recent exports
  ]);

  // Start polling if there are pending exports
  if (hasPendingExports.value) {
    startExportPolling();
  }
});

onBeforeUnmount(() => {
  if (autoRefreshInterval.value) {
    clearInterval(autoRefreshInterval.value);
  }
  stopExportPolling(); // Stop export polling on unmount
  window.removeEventListener('resize', updateAiChatContentWidth);
  contentAreaResizeObserver?.disconnect();
  contentAreaResizeObserver = null;
});

watch(aiChatWidth, updateAiChatContentWidth);
</script>

