// Log severity aliases the raw data uses that don't literally match the
// UI's 4 canonical constants (ERROR/WARN/INFO/DEBUG) — e.g. Python's
// `logging` module spells "WARNING", not "WARN". Mirrors the backend's own
// alias handling in doc2-api's opensearch_client._build_level_filter.
const SEVERITY_ALIASES: Record<string, string[]> = {
  WARN: ['WARN', 'WARNING'],
  WARNING: ['WARN', 'WARNING'],
};

export function logMatchesSelectedSeverities(
  logLevel: string | undefined | null,
  selectedSeverities: string[],
): boolean {
  if (!logLevel) return false;
  const effectiveLevels = new Set(
    selectedSeverities.flatMap((s) => SEVERITY_ALIASES[s] || [s]),
  );
  return effectiveLevels.has(logLevel.toUpperCase());
}

// Collapses a raw log level to one of the 4 canonical UI severities
// (ERROR/WARN/INFO/DEBUG), so counting/coloring code has a single place
// that knows "WARNING" (and any future alias) means "WARN".
export function normalizeLogSeverity(
  logLevel: string | undefined | null,
): string {
  if (!logLevel) return '';
  const upper = logLevel.toUpperCase();
  return upper === 'WARNING' ? 'WARN' : upper;
}
