<template>
  <div class="custom-drawer ai-chat-drawer" :style="{ width: width + 'px' }">
    <div class="resize-handle" @mousedown.prevent="startResize"></div>
    <div class="drawer-space drawer-header">
      <p>{{ $t('ai_log_assistant').toUpperCase() }}</p>
      <span class="q-mb-md close-icon" @click="$emit('close')">
        <Icon icon="mdi:close" width="24" height="24" />
      </span>
    </div>

    <div class="chat-messages" ref="messagesContainer">
      <template v-for="(msg, idx) in messages" :key="idx">
        <div
          class="chat-bubble"
          :class="msg.role === 'user' ? 'chat-bubble--user' : 'chat-bubble--assistant'"
        >
          {{ msg.content }}
        </div>
      </template>

      <div v-if="isStreaming" class="chat-bubble chat-bubble--assistant">
        {{ streamingContent }}<span class="typing-cursor">|</span>
      </div>
    </div>

    <div class="chat-input-area">
      <q-input
        v-model="userInput"
        outlined
        dense
        :placeholder="$t('ai_log_chat_placeholder')"
        @keyup.enter="sendMessage"
        :disable="isStreaming"
        class="chat-input"
      >
        <template v-slot:append>
          <q-btn
            flat
            dense
            round
            icon="send"
            :disable="!userInput.trim() || isStreaming"
            @click="sendMessage"
            color="primary"
          />
        </template>
      </q-input>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, nextTick, onBeforeUnmount } from 'vue';

import { api, getAuthorizationToken } from 'src/pages/APIs';

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export default defineComponent({
  name: 'LogsAiChat',

  props: {
    width: {
      type: Number,
      default: 350,
    },
  },
  emits: ['close', 'update:width'],
  setup(props, { emit }) {
    const messages = ref<ChatMessage[]>([]);
    const userInput = ref('');
    const isStreaming = ref(false);
    const streamingContent = ref('');
    const messagesContainer = ref<HTMLElement | null>(null);

    let abortController: AbortController | null = null;
    let isUnmounted = false;
    let activeMouseMove: ((ev: MouseEvent) => void) | null = null;
    let activeMouseUp: (() => void) | null = null;

    function scrollToBottom() {
      nextTick(() => {
        if (messagesContainer.value) {
          messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
        }
      });
    }

    async function sendMessage() {
      const input = userInput.value.trim();
      if (!input || isStreaming.value) return;

      messages.value.push({ role: 'user', content: input });
      userInput.value = '';
      scrollToBottom();

      isStreaming.value = true;
      streamingContent.value = '';
      abortController = new AbortController();

      try {
        const token = await getAuthorizationToken();

        const response = await fetch(api.logs_ai_chat, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: token || '',
          },
          body: JSON.stringify({ question: input }),
          signal: abortController.signal,
        });

        if (!response.ok) {
          const statusMessages: Record<number, string> = {
            404: 'AI Chat is not available yet. The endpoint may not be deployed.',
            401: 'Authentication failed. Please refresh the page and try again.',
            503: 'AI service is temporarily unavailable. Please try again later.',
          };
          throw new Error(
            statusMessages[response.status] ||
              `Something went wrong (HTTP ${response.status}). Please try again.`,
          );
        }

        const reader = response.body?.getReader();
        if (!reader) throw new Error('No response body');

        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
          const { done, value } = await reader.read();
          if (value) {
            buffer += decoder.decode(value, { stream: true });
          }
          if (done) {
            // Flush any pending multi-byte sequence held by the decoder.
            buffer += decoder.decode();
          }

          const lines = buffer.split('\n');
          // A stream can close without a trailing newline after its last
          // `data:` line — treat whatever's left as complete once done.
          buffer = done ? '' : lines.pop() || '';

          for (const line of lines) {
            if (!line.startsWith('data: ')) continue;
            const data = line.slice(6);
            if (data === '[DONE]') continue;

            try {
              const parsed = JSON.parse(data);
              if (parsed.error) {
                throw new Error(
                  parsed.error.message || 'An error occurred during streaming.',
                );
              }
              if (parsed.delta) {
                streamingContent.value += parsed.delta;
                scrollToBottom();
              }
            } catch (parseErr: any) {
              if (parseErr instanceof SyntaxError) continue;
              throw parseErr;
            }
          }

          if (done) break;
        }

        if (isUnmounted) return;

        if (streamingContent.value) {
          messages.value.push({ role: 'assistant', content: streamingContent.value });
        }
      } catch (err: any) {
        if (isUnmounted || err?.name === 'AbortError') return;
        messages.value.push({
          role: 'assistant',
          content: `Error: ${err.message || 'Failed to get response'}`,
        });
      } finally {
        abortController = null;
        if (!isUnmounted) {
          isStreaming.value = false;
          streamingContent.value = '';
          scrollToBottom();
        }
      }
    }

    function startResize(e: MouseEvent) {
      const startX = e.clientX;
      const startWidth = props.width;
      const onMouseMove = (ev: MouseEvent) => {
        const newWidth = Math.min(700, Math.max(280, startWidth + (startX - ev.clientX)));
        emit('update:width', newWidth);
      };
      const onMouseUp = () => {
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
        activeMouseMove = null;
        activeMouseUp = null;
      };
      activeMouseMove = onMouseMove;
      activeMouseUp = onMouseUp;
      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    }

    onBeforeUnmount(() => {
      isUnmounted = true;
      abortController?.abort();
      if (activeMouseMove) document.removeEventListener('mousemove', activeMouseMove);
      if (activeMouseUp) document.removeEventListener('mouseup', activeMouseUp);
    });

    return {
      messages,
      userInput,
      isStreaming,
      streamingContent,
      messagesContainer,
      sendMessage,
      startResize,
    };
  },
});
</script>

